-- AI/ML pathway ("Cipher Division") Act 26 -- "Large Language Models" content.
-- Arc V, Acts 24-27 (this Act does not close the Arc; Act 27 does).
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue_lines -> objectives ->
-- challenges -> hints pattern as every other pathway Act.
-- Only inserts into campaigns/operations/missions/dialogue_lines/objectives/
-- challenges/hints. The world-ai-large-language-models row already exists.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-large-language-models', 'world-ai-large-language-models', 'large-language-models', '26A - Large Language Models', 'Scale the right decoder-only shape all the way up into something that can hold a conversation, then learn what pretraining, instruction tuning and preference optimization actually did to it -- and why a fluent, confident answer is still not the same thing as a true one.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-large-language-models-1', 'campaign-ai-large-language-models', 'built-from-text', 'Built From Text', 'What an LLM is, how it predicts one token at a time, how text becomes tokens, how far it can see at once, and the three stages of training that turn raw prediction into a model that will actually follow you.', 1),
  ('operation-ai-large-language-models-2', 'campaign-ai-large-language-models', 'confident-but-not-always-right', 'Confident But Not Always Right', 'How a trained model actually generates a reply, the sampling choices that shape it, why it sometimes states fiction with total confidence, and a boss case where that exact failure has to be caught before Cipher Division trusts it.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-large-language-models-01', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-1', 'what-is-an-llm', 'What Is an LLM?', 'The right transformer shape exists for every job now. Cipher Division scales the decoder-only shape all the way up, into something built to hold a conversation.', 'beginner', ARRAY['maya','elena'], null, null, '{"type":"simulation","simulationId":"what-is-an-llm-sim"}'::jsonb, '{"xp":520,"credits":135}'::jsonb, false, 1),
  ('mission-ai-large-language-models-02', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-1', 'next-token-prediction', 'Next-Token Prediction', 'Underneath every fluent reply is the same repeated act: guess the single most likely next token, append it, and do it again.', 'beginner', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-large-language-models-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"next-token-prediction-sim"}'::jsonb, '{"xp":530,"credits":135}'::jsonb, false, 2),
  ('mission-ai-large-language-models-03', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-1', 'tokenizers', 'Tokenizers', 'A model never reads letters or words. It reads tokens -- chunks a tokenizer cuts text into before anything else happens.', 'beginner', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-large-language-models-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"tokenizers-sim"}'::jsonb, '{"xp":530,"credits":140}'::jsonb, false, 3),
  ('mission-ai-large-language-models-04', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-1', 'context-windows', 'Context Windows', 'A model can only attend to a fixed number of tokens at once. Whatever falls outside that window may as well have never been said.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-large-language-models-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"context-windows-sim"}'::jsonb, '{"xp":540,"credits":140}'::jsonb, false, 4),
  ('mission-ai-large-language-models-05', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-1', 'pretraining', 'Pretraining', 'Before a model can do anything useful, it spends most of its compute doing one unglamorous thing: predicting the next token across a huge, largely unlabeled corpus.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-large-language-models-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"pretraining-sim"}'::jsonb, '{"xp":540,"credits":140}'::jsonb, false, 5),
  ('mission-ai-large-language-models-06', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-1', 'instruction-tuning', 'Instruction Tuning', 'A pretrained model completes text. An instruction-tuned model follows a request. Getting from one to the other takes a second, much smaller stage of training.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-large-language-models-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"instruction-tuning-sim"}'::jsonb, '{"xp":550,"credits":145}'::jsonb, false, 6),
  ('mission-ai-large-language-models-07', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-2', 'preference-optimization', 'Preference Optimization', 'Instruction tuning teaches a model to follow a request. Preference optimization teaches it which of several correct-looking replies people actually prefer.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-large-language-models-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"preference-optimization-sim"}'::jsonb, '{"xp":550,"credits":145}'::jsonb, false, 7),
  ('mission-ai-large-language-models-08', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-2', 'inference', 'Inference', 'Training is finished once. Every conversation after that is inference: the frozen model, generating tokens live, in front of whoever is actually talking to it.', 'intermediate', ARRAY['elena','noah'], '{"requiredMissionIds":["mission-ai-large-language-models-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"llm-inference-sim"}'::jsonb, '{"xp":560,"credits":145}'::jsonb, false, 8),
  ('mission-ai-large-language-models-09', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-2', 'temperature', 'Temperature', 'One number decides how much a model is willing to gamble on a less likely token -- and Noah has to pick that number for every production endpoint Cipher Division ships.', 'intermediate', ARRAY['elena','noah'], '{"requiredMissionIds":["mission-ai-large-language-models-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"temperature-sim"}'::jsonb, '{"xp":560,"credits":150}'::jsonb, false, 9),
  ('mission-ai-large-language-models-10', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-2', 'top-k-top-p', 'Top-k/Top-p', 'Temperature reshapes the odds. Top-k and top-p decide how many of those odds are even allowed to be in play before a token gets picked.', 'intermediate', ARRAY['elena','noah'], '{"requiredMissionIds":["mission-ai-large-language-models-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"top-k-top-p-sim"}'::jsonb, '{"xp":570,"credits":150}'::jsonb, false, 10),
  ('mission-ai-large-language-models-11', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-2', 'hallucination', 'Hallucination', 'Nothing in next-token prediction requires the output to be true, only fluent. Sometimes those two things quietly stop being the same thing.', 'intermediate', ARRAY['elena','noah'], '{"requiredMissionIds":["mission-ai-large-language-models-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"hallucination-sim"}'::jsonb, '{"xp":570,"credits":150}'::jsonb, false, 11),
  ('mission-ai-large-language-models-12', 'world-ai-large-language-models', 'campaign-ai-large-language-models', 'operation-ai-large-language-models-2', 'the-confident-lie', 'The Confident Lie', 'The new model is asked to explain Act 23''s strangest connection. It answers fluently, specifically, and with total confidence -- and Cipher Division has to work out how much of that answer is actually real.', 'boss', ARRAY['maya','elena','noah'], '{"requiredMissionIds":["mission-ai-large-language-models-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-confident-lie-boss-sim"}'::jsonb, '{"xp":1300,"credits":280,"badgeIds":["the-confident-lie"],"skillXp":{"llm_engineering":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-large-language-models-01', 1, 'maya', 'The right transformer shape exists for every job now -- encoder-only, decoder-only, encoder-decoder, each one matched to what it is actually for. So Cipher Division is trying something new.'),
  ('mission-ai-large-language-models-01', 2, 'maya', 'We are taking the decoder-only shape, the one built for generation, and scaling it all the way up. More layers, more parameters, a far larger training run than anything we have built this Arc.'),
  ('mission-ai-large-language-models-01', 3, 'elena', 'At that scale it stops behaving like a narrow tool and starts behaving like something you can talk to. A large language model, or LLM: still next-token prediction underneath, just run at a size where fluent conversation falls out of it.'),
  ('mission-ai-large-language-models-01', 4, 'elena', 'It gets there in stages. First it reads a huge, largely unlabeled corpus of text and just practices predicting what comes next -- pretraining. Then it is narrowed toward following actual requests -- instruction tuning. Then it is nudged toward the kinds of answers people actually prefer -- preference optimization.'),
  ('mission-ai-large-language-models-01', 5, 'maya', 'Before we hand this thing anything sensitive, everyone on this team needs to understand exactly what those stages did to it, and what they did not.'),

  ('mission-ai-large-language-models-02', 1, 'elena', 'Strip away everything else and an LLM does one repeated act: given the tokens so far, produce a probability distribution over every possible next token, and pick one.'),
  ('mission-ai-large-language-models-02', 2, 'byte', 'Then that chosen token gets appended to the sequence, and the whole process runs again on the new, slightly longer sequence. One token at a time, every time, until it decides to stop.'),
  ('mission-ai-large-language-models-02', 3, 'elena', 'There is no separate "thinking" step hidden underneath. The fluent paragraph you read is the visible trail of thousands of individual next-token guesses, each one only ever looking backward at what came before it.'),

  ('mission-ai-large-language-models-03', 1, 'elena', 'A model never reads letters or whole words directly. Before anything else happens, a tokenizer cuts the raw text into chunks -- tokens -- and every token gets mapped to a fixed integer ID.'),
  ('mission-ai-large-language-models-03', 2, 'byte', 'Common words often become a single token. Rarer words, made-up terms, and typos frequently get split into several smaller pieces that combine to spell the thing out.'),
  ('mission-ai-large-language-models-03', 3, 'elena', 'That matters for more than curiosity. Everything downstream -- cost, speed, how much fits in the model''s view at once -- is measured in tokens, not characters and not words.'),

  ('mission-ai-large-language-models-04', 1, 'elena', 'A model cannot attend to an unlimited amount of text. It has a context window -- a fixed maximum number of tokens it can hold in view at once, counting both what was said to it and everything it has generated so far.'),
  ('mission-ai-large-language-models-04', 2, 'elena', 'Push a conversation past that limit and the oldest tokens do not get remembered less clearly. They stop being visible to the model at all, as if they were never part of the conversation in the first place.'),

  ('mission-ai-large-language-models-05', 1, 'elena', 'Pretraining is the first and by far the largest stage: predict the next token, check it against the real one, adjust, repeat -- across a huge corpus of ordinary text, mostly without hand-written labels.'),
  ('mission-ai-large-language-models-05', 2, 'elena', 'Nobody sits down and labels "this is a good sentence." The correct answer at each step is just whatever token actually came next in the real text, which is why this stage can run on so much raw data at once.'),
  ('mission-ai-large-language-models-05', 3, 'elena', 'What pretraining produces is a model that is very good at continuing text in a way that matches its corpus. It is not yet a model that reliably does what it is asked. That takes a different kind of training.'),

  ('mission-ai-large-language-models-06', 1, 'elena', 'Ask a purely pretrained model a question and it may not answer it. It may just continue the pattern -- writing three more questions like it, because that is what often follows a question in its training corpus.'),
  ('mission-ai-large-language-models-06', 2, 'elena', 'Instruction tuning fixes that specific gap. The model is trained further on a much smaller, curated set of instruction-and-response pairs, so it learns the shape of the behavior Cipher Division actually wants: read a request, produce a response to it.'),
  ('mission-ai-large-language-models-06', 3, 'elena', 'It is still next-token prediction under the hood. What changed is the data it practiced on, which reshaped what it treats as the pattern worth continuing.'),

  ('mission-ai-large-language-models-07', 1, 'elena', 'Instruction tuning gets a model to attempt the right kind of answer. It does not by itself teach which of several reasonable-looking answers people actually prefer.'),
  ('mission-ai-large-language-models-07', 2, 'elena', 'Preference optimization closes that gap. Humans, or a model trained to imitate human judgment, rank multiple candidate responses to the same prompt, and the model is nudged toward whatever pattern tends to win those rankings.'),
  ('mission-ai-large-language-models-07', 3, 'elena', 'Pretraining teaches it language. Instruction tuning teaches it to follow a request. Preference optimization teaches it which correct-shaped answer people would actually rather receive. Three stages, three different jobs.'),

  ('mission-ai-large-language-models-08', 1, 'noah', 'All three training stages already happened, offline, before any of this ever reaches a user. Every conversation you have with the deployed model afterward is inference -- the trained parameters held fixed, generating tokens live.'),
  ('mission-ai-large-language-models-08', 2, 'elena', 'Same next-token loop from earlier, just running at serving time instead of training time: read the tokens so far, produce a next-token distribution, sample from it, append, repeat -- until a stop condition is hit.'),
  ('mission-ai-large-language-models-08', 3, 'noah', 'From where I sit that loop is a production system like any other. It has a latency budget, a cost per token, and it can be misconfigured just like a database connection pool can.'),

  ('mission-ai-large-language-models-09', 1, 'noah', 'One of the knobs I own is temperature. It rescales the next-token distribution before a token gets sampled. Low temperature sharpens it toward the single most likely token. High temperature flattens it, giving less likely tokens a real chance.'),
  ('mission-ai-large-language-models-09', 2, 'elena', 'Temperature at zero is nearly deterministic -- close to always taking the top choice. Push it high and output gets more varied, and eventually more incoherent, because genuinely unlikely tokens start getting picked.'),
  ('mission-ai-large-language-models-09', 3, 'noah', 'Which means the "right" temperature depends entirely on the job. A factual lookup wants it low and boring. Creative brainstorming can tolerate it high. Cipher Division has been shipping every endpoint at the same default, and that was never actually a neutral choice.'),

  ('mission-ai-large-language-models-10', 1, 'noah', 'Temperature reshapes the odds across the whole vocabulary. Top-k and top-p decide how many of those odds are even allowed to compete before a token gets sampled.'),
  ('mission-ai-large-language-models-10', 2, 'elena', 'Top-k keeps only the k highest-probability tokens and samples among just those, discarding the long tail outright. Top-p, nucleus sampling, instead keeps the smallest set of top tokens whose probabilities add up to at least p, so the cutoff shrinks or grows with how confident the distribution already is.'),
  ('mission-ai-large-language-models-10', 3, 'noah', 'In production these get combined with temperature, not swapped in for it. Restrict the candidate pool first, then let temperature decide how sharply to choose among whatever survived.'),

  ('mission-ai-large-language-models-11', 1, 'elena', 'Nothing in next-token prediction requires an output to be true. It only requires the next token to be a plausible continuation of everything so far, given what the model learned from its training data.'),
  ('mission-ai-large-language-models-11', 2, 'noah', 'Most of the time plausible and true line up closely enough that nobody notices the difference. Hallucination is what it is called when they quietly stop lining up -- a fluent, confident, specific claim that simply is not supported by anything real.'),
  ('mission-ai-large-language-models-11', 3, 'elena', 'The dangerous part is not that the model is wrong. Models are wrong constantly. The dangerous part is that a hallucinated answer reads exactly as confident as a correct one -- fluency was never a signal of truth, it only ever felt like one.'),

  ('mission-ai-large-language-models-12', 1, 'maya', 'Act 23 left us with a strange fact nobody has explained: Echo''s most recent unusual message sits closest, in meaning, to something from its very first hours of activation. We asked the new model to explain why.'),
  ('mission-ai-large-language-models-12', 2, 'elena', 'It gave us an answer. Fluent, detailed, specific -- it reads like it was written by someone who actually knows. Before Cipher Division acts on a word of it, we check every claim in it against the real evidence trail.'),
  ('mission-ai-large-language-models-12', 3, 'noah', 'This is exactly the failure mode I flagged in Hallucination, except now it is sitting in front of a live decision instead of a training exercise. A hallucinating model in production does not announce itself. It just sounds right.'),
  ('mission-ai-large-language-models-12', 4, 'maya', 'So do the job properly. Find what the explanation actually gets right against our evidence, weigh whether sounding confident is worth anything on its own, and tell me whether Cipher Division can use this answer or has to throw it out.'),
  ('mission-ai-large-language-models-12', 5, 'maya', 'A model this confident, even when it is wrong, is not something Cipher Division can run on instinct. Every output this tool ever produces now needs structure, validation and a way to fail safely -- starting with how it is even allowed to respond.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-large-language-models-01-o1', 'mission-ai-large-language-models-01', 1, 'Define an LLM', 'State what actually makes a large language model "large" and what stays the same underneath.'),
  ('mission-ai-large-language-models-01-o2', 'mission-ai-large-language-models-01', 2, 'Order the training stages', 'Put pretraining, instruction tuning and preference optimization in the order they actually happen.'),

  ('mission-ai-large-language-models-02-o1', 'mission-ai-large-language-models-02', 1, 'Define next-token prediction', 'State what a language model actually predicts at each generation step.'),
  ('mission-ai-large-language-models-02-o2', 'mission-ai-large-language-models-02', 2, 'Trace the generation loop', 'Order the repeated steps that turn one next-token prediction into a full reply.'),

  ('mission-ai-large-language-models-03-o1', 'mission-ai-large-language-models-03', 1, 'Define a token', 'Identify what a tokenizer actually produces from raw text.'),
  ('mission-ai-large-language-models-03-o2', 'mission-ai-large-language-models-03', 2, 'Predict tokenization behavior', 'Sort example inputs by whether a tokenizer would likely keep them as one token or split them into several.'),

  ('mission-ai-large-language-models-04-o1', 'mission-ai-large-language-models-04', 1, 'Define a context window', 'State what a context window actually limits.'),
  ('mission-ai-large-language-models-04-o2', 'mission-ai-large-language-models-04', 2, 'Diagnose a context-window failure', 'Find the evidence explaining why a long-running conversation forgot an early instruction.'),

  ('mission-ai-large-language-models-05-o1', 'mission-ai-large-language-models-05', 1, 'Define pretraining', 'State what pretraining actually trains a model to do.'),
  ('mission-ai-large-language-models-05-o2', 'mission-ai-large-language-models-05', 2, 'Know its limits', 'Identify what a purely pretrained model is not yet reliable at.'),

  ('mission-ai-large-language-models-06-o1', 'mission-ai-large-language-models-06', 1, 'Define instruction tuning', 'State what instruction tuning changes relative to a purely pretrained model.'),
  ('mission-ai-large-language-models-06-o2', 'mission-ai-large-language-models-06', 2, 'Match the training stage to its data', 'Pair each training stage with the kind of data it actually trains on.'),

  ('mission-ai-large-language-models-07-o1', 'mission-ai-large-language-models-07', 1, 'Define preference optimization', 'State what preference optimization actually optimizes for.'),
  ('mission-ai-large-language-models-07-o2', 'mission-ai-large-language-models-07', 2, 'Match each stage to its job', 'Pair pretraining, instruction tuning and preference optimization with what each one is actually responsible for.'),

  ('mission-ai-large-language-models-08-o1', 'mission-ai-large-language-models-08', 1, 'Define inference', 'State what is fixed and what is happening live during inference.'),
  ('mission-ai-large-language-models-08-o2', 'mission-ai-large-language-models-08', 2, 'Separate training-time from serving-time', 'Sort concerns into ones that belong to training or ones that belong to inference.'),

  ('mission-ai-large-language-models-09-o1', 'mission-ai-large-language-models-09', 1, 'Define temperature', 'State what temperature actually does to the next-token distribution.'),
  ('mission-ai-large-language-models-09-o2', 'mission-ai-large-language-models-09', 2, 'Match temperature to the job', 'Pair each task with the temperature setting best suited to it.'),

  ('mission-ai-large-language-models-10-o1', 'mission-ai-large-language-models-10', 1, 'Distinguish top-k from top-p', 'State the difference between how top-k and top-p restrict the candidate token pool.'),
  ('mission-ai-large-language-models-10-o2', 'mission-ai-large-language-models-10', 2, 'Order the sampling pipeline', 'Put candidate restriction and temperature scaling in the order a production sampler actually applies them.'),

  ('mission-ai-large-language-models-11-o1', 'mission-ai-large-language-models-11', 1, 'Define hallucination', 'State what hallucination actually is, in terms of plausibility versus truth.'),
  ('mission-ai-large-language-models-11-o2', 'mission-ai-large-language-models-11', 2, 'Catch a hallucination in the wild', 'Find the evidence proving a model-generated claim is not supported by the real record.'),

  ('mission-ai-large-language-models-12-o1', 'mission-ai-large-language-models-12', 1, 'Check Every Claim', 'Find which specific claims in the model''s explanation are unsupported by the real Act 23 evidence trail.'),
  ('mission-ai-large-language-models-12-o2', 'mission-ai-large-language-models-12', 2, 'Weigh Confidence Against Evidence', 'Judge why a fluent, confident tone is not itself evidence that an explanation is true.'),
  ('mission-ai-large-language-models-12-o3', 'mission-ai-large-language-models-12', 3, 'Rule on the Explanation', 'Decide whether Cipher Division can use the model''s explanation, partially trust it, or must reject it outright.'),
  ('mission-ai-large-language-models-12-o4', 'mission-ai-large-language-models-12', 4, 'Close the Case', 'Bring the three judgments together into Cipher Division''s final call on the explanation.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-large-language-models-01-o1-c1', 'mission-ai-large-language-models-01-o1', 1, 'multiple_choice', 'What actually makes a large language model "large," compared to the decoder-only transformers built earlier this Arc?', '{"question":"What actually makes a large language model \"large,\" compared to the decoder-only transformers built earlier this Arc?","options":[{"id":"a","text":"It uses a completely different mechanism than next-token prediction"},{"id":"b","text":"The same decoder-only, next-token-prediction shape, scaled up in parameters and training data until fluent conversation emerges"},{"id":"c","text":"It is trained without any data at all"},{"id":"d","text":"It replaces attention with a rule-based lookup table"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-large-language-models-01-o2-c1', 'mission-ai-large-language-models-01-o2', 1, 'interactive_diagram', 'Order the stages that turn a scaled-up decoder-only model into something that follows requests and matches human preference.', '{"diagramId":"llm-training-pipeline","hotspots":[{"id":"pretrain","label":"Pretraining","explanation":"The model practices next-token prediction across a huge, largely unlabeled corpus of text."},{"id":"instruct","label":"Instruction tuning","explanation":"The model is trained further on a smaller set of instruction-and-response pairs, learning to follow a request."},{"id":"preference","label":"Preference optimization","explanation":"The model is nudged toward whichever of several correct-shaped answers people actually prefer."},{"id":"deploy","label":"Deployment (inference)","explanation":"The finished, frozen model generates replies live for real conversations."}],"task":"Order the stages from first to last."}'::jsonb, '{"correctOrderIds":["pretrain","instruct","preference","deploy"]}'::jsonb),

  ('mission-ai-large-language-models-02-o1-c1', 'mission-ai-large-language-models-02-o1', 1, 'multiple_choice', 'At each generation step, what does a language model actually predict?', '{"question":"At each generation step, what does a language model actually predict?","options":[{"id":"a","text":"The entire final response in one shot"},{"id":"b","text":"A probability distribution over what the next single token should be, given the tokens so far"},{"id":"c","text":"Whether the user''s question is true or false"},{"id":"d","text":"The next paragraph, then the next sentence within it"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-large-language-models-02-o2-c1', 'mission-ai-large-language-models-02-o2', 1, 'interactive_diagram', 'Order the repeated steps that turn a single next-token prediction into a full generated reply.', '{"diagramId":"next-token-loop","hotspots":[{"id":"read","label":"Read the tokens so far","explanation":"The model looks at everything generated or given to it up to this point."},{"id":"distribute","label":"Produce a probability distribution over the next token","explanation":"Every possible next token gets a probability based on what came before."},{"id":"pick","label":"Pick one token","explanation":"A token is chosen from that distribution."},{"id":"append","label":"Append it to the sequence","explanation":"The chosen token becomes part of the sequence the next step will read."},{"id":"repeat","label":"Repeat until a stop condition is reached","explanation":"The whole loop runs again on the new, longer sequence, until the model stops or a limit is hit."}],"task":"Order the steps of the generation loop from first to last."}'::jsonb, '{"correctOrderIds":["read","distribute","pick","append","repeat"]}'::jsonb),

  ('mission-ai-large-language-models-03-o1-c1', 'mission-ai-large-language-models-03-o1', 1, 'multiple_choice', 'What does a tokenizer actually produce from raw input text?', '{"question":"What does a tokenizer actually produce from raw input text?","options":[{"id":"a","text":"A list of whole sentences"},{"id":"b","text":"A sequence of tokens, each mapped to a fixed integer ID, which may be whole words, word pieces, or single characters"},{"id":"c","text":"A translated version of the text in another language"},{"id":"d","text":"A summary of the text"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-large-language-models-03-o2-c1', 'mission-ai-large-language-models-03-o2', 1, 'drag_and_drop', 'Sort each input by whether a typical tokenizer would likely keep it as one token or split it into several.', '{"items":[{"id":"w1","text":"the"},{"id":"w2","text":"cybersecurity"},{"id":"w3","text":"a"},{"id":"w4","text":"xqzzyplex"},{"id":"w5","text":"is"}],"targets":[{"id":"one","label":"Likely one token"},{"id":"several","label":"Likely split into several tokens"}]}'::jsonb, '{"correctMapping":{"w1":"one","w2":"several","w3":"one","w4":"several","w5":"one"}}'::jsonb),

  ('mission-ai-large-language-models-04-o1-c1', 'mission-ai-large-language-models-04-o1', 1, 'multiple_choice', 'What does a context window actually limit?', '{"question":"What does a context window actually limit?","options":[{"id":"a","text":"How many conversations a model can run at the same time"},{"id":"b","text":"The maximum number of tokens, counting both input and generated output, the model can attend to at once"},{"id":"c","text":"How many users can talk to the model per second"},{"id":"d","text":"The physical storage size of the model''s parameters"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-large-language-models-04-o2-c1', 'mission-ai-large-language-models-04-o2', 1, 'investigation', 'A user gave an instruction early in a very long conversation. Thousands of tokens later, the model ignores it completely. Which evidence explains why?', '{"evidence":[{"id":"e1","label":"Session log","detail":"Total tokens in the conversation now exceed the model''s context window; the earliest tokens, including the original instruction, are no longer part of what the model attends to"},{"id":"e2","label":"Latency log","detail":"Response times have stayed roughly constant throughout the conversation"},{"id":"e3","label":"Billing note","detail":"The account has an active subscription with no usage cap reached"}],"question":"Which evidence explains why the model stopped following an instruction given early in a long conversation?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-large-language-models-05-o1-c1', 'mission-ai-large-language-models-05-o1', 1, 'multiple_choice', 'Pretraining trains a model to do what?', '{"question":"Pretraining trains a model to do what?","options":[{"id":"a","text":"Follow explicit user instructions reliably"},{"id":"b","text":"Predict the next token across a huge corpus of largely unlabeled text"},{"id":"c","text":"Rank multiple candidate answers by human preference"},{"id":"d","text":"Classify text into fixed categories"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-large-language-models-05-o2-c1', 'mission-ai-large-language-models-05-o2', 1, 'multiple_choice', 'A purely pretrained model, asked a direct question, is most likely to...', '{"question":"A purely pretrained model, asked a direct question, is most likely to...","options":[{"id":"a","text":"Always answer it correctly and concisely"},{"id":"b","text":"Continue the text in whatever pattern its corpus suggests, which may not be a direct answer at all"},{"id":"c","text":"Refuse to produce any output"},{"id":"d","text":"Immediately ask a clarifying question every time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-large-language-models-06-o1-c1', 'mission-ai-large-language-models-06-o1', 1, 'multiple_choice', 'What does instruction tuning change relative to a purely pretrained model?', '{"question":"What does instruction tuning change relative to a purely pretrained model?","options":[{"id":"a","text":"It changes the model''s architecture from decoder-only to encoder-decoder"},{"id":"b","text":"It trains the model further on instruction-and-response pairs, shaping it to read a request and produce a response to it"},{"id":"c","text":"It removes next-token prediction entirely"},{"id":"d","text":"It only changes how the model is tokenized"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-large-language-models-06-o2-c1', 'mission-ai-large-language-models-06-o2', 1, 'drag_and_drop', 'Match each training stage to the kind of data it actually trains on.', '{"items":[{"id":"d1","text":"A huge, largely unlabeled corpus of ordinary text"},{"id":"d2","text":"A smaller, curated set of instruction-and-response pairs"},{"id":"d3","text":"Rankings of multiple candidate responses to the same prompt"}],"targets":[{"id":"pretrain","label":"Pretraining"},{"id":"instruct","label":"Instruction tuning"},{"id":"preference","label":"Preference optimization"}]}'::jsonb, '{"correctMapping":{"d1":"pretrain","d2":"instruct","d3":"preference"}}'::jsonb),

  ('mission-ai-large-language-models-07-o1-c1', 'mission-ai-large-language-models-07-o1', 1, 'multiple_choice', 'Preference optimization is best described as optimizing for what?', '{"question":"Preference optimization is best described as optimizing for what?","options":[{"id":"a","text":"Which of several reasonable-looking responses people actually prefer, not just whether a response is a valid attempt"},{"id":"b","text":"How quickly the model generates tokens"},{"id":"c","text":"How large the model''s vocabulary is"},{"id":"d","text":"How many languages the model supports"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-large-language-models-07-o2-c1', 'mission-ai-large-language-models-07-o2', 1, 'drag_and_drop', 'Match each training stage to what it is actually responsible for.', '{"items":[{"id":"job1","text":"Teaching the model language and general knowledge from raw text"},{"id":"job2","text":"Teaching the model to read a request and produce a response to it"},{"id":"job3","text":"Teaching the model which correct-shaped answer people would rather receive"}],"targets":[{"id":"pretrain","label":"Pretraining"},{"id":"instruct","label":"Instruction tuning"},{"id":"preference","label":"Preference optimization"}]}'::jsonb, '{"correctMapping":{"job1":"pretrain","job2":"instruct","job3":"preference"}}'::jsonb),

  ('mission-ai-large-language-models-08-o1-c1', 'mission-ai-large-language-models-08-o1', 1, 'multiple_choice', 'During inference, what is fixed and what is happening live?', '{"question":"During inference, what is fixed and what is happening live?","options":[{"id":"a","text":"The model''s parameters are fixed; tokens are generated live in response to the current input"},{"id":"b","text":"The model''s parameters are still being updated live from the conversation"},{"id":"c","text":"Both the parameters and the training data change live"},{"id":"d","text":"Nothing changes and nothing is generated; inference only retrieves cached answers"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-large-language-models-08-o2-c1', 'mission-ai-large-language-models-08-o2', 1, 'drag_and_drop', 'Sort each concern by whether it belongs to training time or inference (serving) time.', '{"items":[{"id":"c1","text":"Adjusting parameters based on prediction error"},{"id":"c2","text":"Per-request latency budget"},{"id":"c3","text":"Curating the instruction-and-response dataset"},{"id":"c4","text":"Cost per generated token"}],"targets":[{"id":"training","label":"Training time"},{"id":"inference","label":"Inference (serving) time"}]}'::jsonb, '{"correctMapping":{"c1":"training","c2":"inference","c3":"training","c4":"inference"}}'::jsonb),

  ('mission-ai-large-language-models-09-o1-c1', 'mission-ai-large-language-models-09-o1', 1, 'multiple_choice', 'What does raising temperature do to the next-token distribution?', '{"question":"What does raising temperature do to the next-token distribution?","options":[{"id":"a","text":"It flattens the distribution, giving less likely tokens a greater chance of being picked"},{"id":"b","text":"It sharpens the distribution toward only the single most likely token"},{"id":"c","text":"It has no effect on which token gets chosen"},{"id":"d","text":"It changes the tokenizer''s vocabulary"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-large-language-models-09-o2-c1', 'mission-ai-large-language-models-09-o2', 1, 'drag_and_drop', 'Match each task to the temperature setting best suited to it.', '{"items":[{"id":"t1","text":"Looking up a precise factual answer"},{"id":"t2","text":"Brainstorming varied creative story ideas"},{"id":"t3","text":"Extracting a structured value from a document, consistently"}],"targets":[{"id":"low","label":"Low temperature"},{"id":"high","label":"High temperature"}]}'::jsonb, '{"correctMapping":{"t1":"low","t2":"high","t3":"low"}}'::jsonb),

  ('mission-ai-large-language-models-10-o1-c1', 'mission-ai-large-language-models-10-o1', 1, 'multiple_choice', 'What is the actual difference between how top-k and top-p restrict the candidate token pool?', '{"question":"What is the actual difference between how top-k and top-p restrict the candidate token pool?","options":[{"id":"a","text":"Top-k always keeps exactly k tokens; top-p keeps the smallest set of top tokens whose probabilities sum to at least p, so its size varies with the distribution''s shape"},{"id":"b","text":"They are two names for the exact same mechanism"},{"id":"c","text":"Top-k restricts context length; top-p restricts vocabulary size"},{"id":"d","text":"Top-p only works on the first token of a response"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-large-language-models-10-o2-c1', 'mission-ai-large-language-models-10-o2', 1, 'interactive_diagram', 'Order the steps a production sampler actually applies before a token is chosen.', '{"diagramId":"sampling-pipeline","hotspots":[{"id":"raw","label":"Compute the raw next-token probability distribution","explanation":"The model produces a probability for every token in its vocabulary."},{"id":"restrict","label":"Restrict the candidate pool with top-k or top-p","explanation":"Only the surviving high-probability tokens remain eligible to be sampled."},{"id":"scale","label":"Apply temperature to the remaining candidates","explanation":"Temperature reshapes the odds among whatever tokens survived the restriction."},{"id":"sample","label":"Sample the next token from the reshaped distribution","explanation":"A single token is drawn according to the final, adjusted probabilities."}],"task":"Order the steps a production sampler applies, from first to last."}'::jsonb, '{"correctOrderIds":["raw","restrict","scale","sample"]}'::jsonb),

  ('mission-ai-large-language-models-11-o1-c1', 'mission-ai-large-language-models-11-o1', 1, 'multiple_choice', 'Hallucination is best defined as...', '{"question":"Hallucination is best defined as...","options":[{"id":"a","text":"Any response the user personally disagrees with"},{"id":"b","text":"A fluent, confident, specific claim generated because it was a plausible continuation of the text, without actually being supported by anything real"},{"id":"c","text":"A model crashing mid-response"},{"id":"d","text":"A response that takes unusually long to generate"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-large-language-models-11-o2-c1', 'mission-ai-large-language-models-11-o2', 1, 'investigation', 'A model states a specific statistic about Cipher Division''s Act 21 tool that sounds precise and reasonable. Which evidence would actually prove it is a hallucination?', '{"evidence":[{"id":"e1","label":"Model output","detail":"The statistic is stated fluently, in a confident and specific tone"},{"id":"e2","label":"Real record check","detail":"No document, log, or report anywhere in Cipher Division''s archive contains that statistic or anything it could have been derived from"},{"id":"e3","label":"Response length","detail":"The full response is several paragraphs long"}],"question":"Which evidence would actually prove the statistic is a hallucination rather than a real fact?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-large-language-models-12-o1-c1', 'mission-ai-large-language-models-12-o1', 1, 'investigation', 'The model''s explanation makes several specific claims about why Echo''s recent message matches its earliest activation data. Check each claim against the real Act 23 evidence trail. Which claims are actually unsupported?', '{"evidence":[{"id":"model-claim-1","label":"Model claim: shared origin phrase","detail":"The model states both messages were generated from what it calls a fixed \"origin phrase template\" it says Echo was seeded with -- no such template, seed value, or origin phrase appears anywhere in the real Act 23 records or Echo''s recovered activation logs"},{"id":"model-claim-2","label":"Model claim: recurring internal counter","detail":"The model states an internal \"cycle counter\" inside Echo reset at the exact moment of both messages, causing the similarity -- Echo''s architecture has no documented counter of that kind, and nothing in the evidence trail measures or references one"},{"id":"real-e1","label":"Real evidence: Act 23 embedding comparison","detail":"The actual, verified finding: the two messages are closest to each other by semantic embedding distance, out of everything in Echo''s full logged history -- this part is real and already established"},{"id":"model-claim-3","label":"Model claim: deliberate design choice","detail":"The model states this proves Echo''s original creators deliberately designed it to echo its first message later on purpose -- no design document, creator record, or specification of any kind exists to support this; the creators'' records remain missing entirely"}],"question":"Which of the model''s specific claims are unsupported by the real Act 23 evidence trail?"}'::jsonb, '{"requiredEvidenceIds":["model-claim-1","model-claim-2","model-claim-3"]}'::jsonb),
  ('mission-ai-large-language-models-12-o2-c1', 'mission-ai-large-language-models-12-o2', 1, 'multiple_choice', 'Why is the fluent, confident tone of the model''s explanation not itself evidence that the explanation is true?', '{"question":"Why is the fluent, confident tone of the model''s explanation not itself evidence that the explanation is true?","options":[{"id":"a","text":"Because confident-sounding text is always wrong"},{"id":"b","text":"Because next-token prediction only optimizes for a plausible, fluent continuation, not for factual grounding -- a hallucinated claim and a true one can read identically confident"},{"id":"c","text":"Because the model was not using instruction tuning for this answer"},{"id":"d","text":"Because longer answers are always less accurate than short ones"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-large-language-models-12-o3-c1', 'mission-ai-large-language-models-12-o3', 1, 'multiple_choice', 'Given that its specific causal claims are unsupported by the real evidence trail, what should Cipher Division do with the model''s explanation?', '{"question":"Given that its specific causal claims are unsupported by the real evidence trail, what should Cipher Division do with the model''s explanation?","options":[{"id":"a","text":"Accept it fully, since it is well written and internally consistent"},{"id":"b","text":"Reject the explanation entirely -- the real embedding similarity from Act 23 still stands, but why it exists remains unknown, and none of the model''s specific reasons should be treated as fact"},{"id":"c","text":"Accept the parts that sound most technical and discard the rest"},{"id":"d","text":"Treat it as probably true since no one has disproved it yet"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-large-language-models-12-o4-c1', 'mission-ai-large-language-models-12-o4', 1, 'boss_encounter', 'Bring the three judgments together into Cipher Division''s final call on the model''s explanation.', '{"stages":[{"objectiveRef":"mission-ai-large-language-models-12-o1","label":"Check Every Claim"},{"objectiveRef":"mission-ai-large-language-models-12-o2","label":"Weigh Confidence Against Evidence"},{"objectiveRef":"mission-ai-large-language-models-12-o3","label":"Rule on the Explanation"}],"task":"State Cipher Division''s final call: reject the model''s specific explanation as unsupported hallucination, while keeping the real Act 23 embedding-similarity finding as still true and still unexplained."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-large-language-models-12-o1","mission-ai-large-language-models-12-o2","mission-ai-large-language-models-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-large-language-models-01-o1-c1', 'orientation', 'Nothing about the underlying prediction mechanism changed between last Act''s decoder-only models and this one.', 10, 1),
  ('mission-ai-large-language-models-01-o1-c1', 'solution', 'An LLM is the same decoder-only, next-token-prediction shape, scaled up in parameters and training data until it can hold a fluent conversation.', 20, 2),
  ('mission-ai-large-language-models-01-o2-c1', 'orientation', 'A model has to be able to complete text before it can be taught to follow a request, and it has to attempt requests before its answers can be ranked.', 10, 1),
  ('mission-ai-large-language-models-01-o2-c1', 'solution', 'Pretraining, then instruction tuning, then preference optimization, then deployment for real conversations.', 20, 2),

  ('mission-ai-large-language-models-02-o1-c1', 'orientation', 'The model never commits to a whole sentence in one step. It only ever commits to one unit at a time.', 10, 1),
  ('mission-ai-large-language-models-02-o1-c1', 'solution', 'At each step it produces a probability distribution over the single next token, given everything generated or given so far.', 20, 2),
  ('mission-ai-large-language-models-02-o2-c1', 'orientation', 'Nothing can be picked before a distribution exists, and nothing can be appended before a token has been picked.', 10, 1),
  ('mission-ai-large-language-models-02-o2-c1', 'concept', 'The loop has to run again on the newly extended sequence -- that repetition is what turns one prediction into a full reply.', 20, 2),
  ('mission-ai-large-language-models-02-o2-c1', 'solution', 'Read the tokens so far, produce a next-token distribution, pick one, append it, and repeat until a stop condition is reached.', 30, 3),

  ('mission-ai-large-language-models-03-o1-c1', 'orientation', 'A tokenizer''s job happens before the model ever sees anything -- it turns text into the units the model actually operates on.', 10, 1),
  ('mission-ai-large-language-models-03-o1-c1', 'solution', 'A tokenizer produces a sequence of tokens, each mapped to a fixed integer ID -- sometimes whole words, sometimes smaller word pieces or characters.', 20, 2),
  ('mission-ai-large-language-models-03-o2-c1', 'orientation', 'Common, short, frequently seen words tend to survive as one token. Rare or made-up words tend to get broken apart.', 10, 1),
  ('mission-ai-large-language-models-03-o2-c1', 'solution', 'One token: the, a, is -- extremely common short words. Several tokens: cybersecurity, xqzzyplex -- longer or unfamiliar strings a tokenizer is more likely to split.', 20, 2),

  ('mission-ai-large-language-models-04-o1-c1', 'orientation', 'The limit applies to what the model can attend to right now, not to how much it was ever trained on.', 10, 1),
  ('mission-ai-large-language-models-04-o1-c1', 'solution', 'A context window is the maximum number of tokens, input plus generated output combined, that the model can attend to at once.', 20, 2),
  ('mission-ai-large-language-models-04-o2-c1', 'orientation', 'Ask what happens to the oldest part of a conversation once the token count grows past the model''s limit.', 10, 1),
  ('mission-ai-large-language-models-04-o2-c1', 'solution', 'e1: once the conversation exceeds the context window, the earliest tokens, including the original instruction, fall outside what the model can attend to at all.', 20, 2),

  ('mission-ai-large-language-models-05-o1-c1', 'orientation', 'This is the same next-token-prediction task from earlier missions, just run at a much larger scale.', 10, 1),
  ('mission-ai-large-language-models-05-o1-c1', 'solution', 'Pretraining trains a model to predict the next token across a huge, largely unlabeled corpus of ordinary text.', 20, 2),
  ('mission-ai-large-language-models-05-o2-c1', 'orientation', 'Predicting a likely continuation is not the same skill as recognizing and directly answering a question.', 10, 1),
  ('mission-ai-large-language-models-05-o2-c1', 'solution', 'A purely pretrained model tends to continue the pattern its corpus suggests, which may not be a direct answer at all -- it has not yet been trained to recognize and fulfill a request.', 20, 2),

  ('mission-ai-large-language-models-06-o1-c1', 'orientation', 'The mechanism underneath does not change. What changes is the data the model is trained on next.', 10, 1),
  ('mission-ai-large-language-models-06-o1-c1', 'solution', 'Instruction tuning trains the model further on instruction-and-response pairs, shaping it to read a request and produce a response to it.', 20, 2),
  ('mission-ai-large-language-models-06-o2-c1', 'orientation', 'Match scale of data to stage: the biggest, least curated dataset comes first; the most structured, ranked one comes last.', 10, 1),
  ('mission-ai-large-language-models-06-o2-c1', 'solution', 'Pretraining -> huge unlabeled corpus. Instruction tuning -> curated instruction-and-response pairs. Preference optimization -> rankings of candidate responses.', 20, 2),

  ('mission-ai-large-language-models-07-o1-c1', 'orientation', 'Instruction tuning already gets the model attempting a real answer. This stage is about choosing between several real attempts.', 10, 1),
  ('mission-ai-large-language-models-07-o1-c1', 'solution', 'Preference optimization optimizes for which of several reasonable-looking responses people actually prefer, not just whether a response is a valid attempt.', 20, 2),
  ('mission-ai-large-language-models-07-o2-c1', 'orientation', 'Language first, then following a request, then choosing the preferred version of a correct response -- match each job to its stage.', 10, 1),
  ('mission-ai-large-language-models-07-o2-c1', 'solution', 'Pretraining -> teaches language and general knowledge. Instruction tuning -> teaches following a request. Preference optimization -> teaches which correct-shaped answer people prefer.', 20, 2),

  ('mission-ai-large-language-models-08-o1-c1', 'orientation', 'Ask which part of the model was already finished before this conversation even started.', 10, 1),
  ('mission-ai-large-language-models-08-o1-c1', 'solution', 'The model''s parameters are fixed, set during training; tokens are generated live, in response to whatever input arrives now.', 20, 2),
  ('mission-ai-large-language-models-08-o2-c1', 'orientation', 'Ask whether each concern involves parameters changing, or a live request being served.', 10, 1),
  ('mission-ai-large-language-models-08-o2-c1', 'solution', 'Training time: adjusting parameters, curating the instruction dataset. Inference time: per-request latency, cost per generated token.', 20, 2),

  ('mission-ai-large-language-models-09-o1-c1', 'orientation', 'Think about what happens to the gap between the most likely token and everything else as temperature rises.', 10, 1),
  ('mission-ai-large-language-models-09-o1-c1', 'solution', 'Raising temperature flattens the next-token distribution, giving less likely tokens a real chance of being sampled instead of only the top one.', 20, 2),
  ('mission-ai-large-language-models-09-o2-c1', 'orientation', 'Ask which tasks need the single most reliable answer, and which benefit from variety.', 10, 1),
  ('mission-ai-large-language-models-09-o2-c1', 'solution', 'Low temperature: precise factual lookup, consistent structured extraction. High temperature: brainstorming varied creative ideas.', 20, 2),

  ('mission-ai-large-language-models-10-o1-c1', 'orientation', 'One of these methods always keeps a fixed count of candidates. The other keeps however many are needed to reach a probability total.', 10, 1),
  ('mission-ai-large-language-models-10-o1-c1', 'solution', 'Top-k always keeps exactly k tokens. Top-p keeps the smallest set of top tokens whose probabilities sum to at least p, so its size shifts with how confident the distribution already is.', 20, 2),
  ('mission-ai-large-language-models-10-o2-c1', 'orientation', 'The candidate pool has to be narrowed before temperature decides how sharply to choose among what is left.', 10, 1),
  ('mission-ai-large-language-models-10-o2-c1', 'concept', 'Nothing can be sampled before a final, adjusted distribution exists to sample from.', 20, 2),
  ('mission-ai-large-language-models-10-o2-c1', 'solution', 'Compute the raw distribution, restrict candidates with top-k or top-p, apply temperature to what survived, then sample the next token.', 30, 3),

  ('mission-ai-large-language-models-11-o1-c1', 'orientation', 'The model never checks its output against reality. It only checks whether the next token fits the pattern.', 10, 1),
  ('mission-ai-large-language-models-11-o1-c1', 'solution', 'Hallucination is a fluent, confident, specific claim generated because it was a plausible continuation of the text, without being supported by anything real.', 20, 2),
  ('mission-ai-large-language-models-11-o2-c1', 'orientation', 'Confidence and length do not tell you whether a claim is grounded. Only checking it against a real source does.', 10, 1),
  ('mission-ai-large-language-models-11-o2-c1', 'solution', 'e2: no document, log, or report anywhere in the archive contains or supports the statistic -- that absence is what actually proves it is a hallucination.', 20, 2),

  ('mission-ai-large-language-models-12-o1-c1', 'orientation', 'Check each specific claim against the real Act 23 record on its own, rather than judging the explanation as one fluent whole.', 10, 1),
  ('mission-ai-large-language-models-12-o1-c1', 'concept', 'The real Act 23 finding was only ever that the two messages are closest by embedding distance. Anything the model adds beyond that needs its own separate support.', 20, 2),
  ('mission-ai-large-language-models-12-o1-c1', 'solution', 'The origin-phrase template, the internal cycle counter, and the claim of deliberate creator design are all unsupported -- none of them appear anywhere in the real evidence trail. Only the embedding-similarity finding itself is real.', 30, 3),
  ('mission-ai-large-language-models-12-o2-c1', 'orientation', 'Ask what next-token prediction actually optimizes for at generation time, and whether truth is part of that.', 10, 1),
  ('mission-ai-large-language-models-12-o2-c1', 'solution', 'Next-token prediction only optimizes for a plausible, fluent continuation, not for factual grounding, so a hallucinated claim can read exactly as confident as a true one.', 20, 2),
  ('mission-ai-large-language-models-12-o3-c1', 'orientation', 'A partially convincing explanation with unsupported specifics is still an unsupported explanation.', 10, 1),
  ('mission-ai-large-language-models-12-o3-c1', 'solution', 'Reject the explanation entirely. The real embedding similarity from Act 23 still stands, but why it exists remains unknown, and none of the model''s specific reasons should be treated as fact.', 20, 2),
  ('mission-ai-large-language-models-12-o4-c1', 'orientation', 'Bring together what was checked, why confidence did not settle it, and what the actual ruling has to be.', 15, 1),
  ('mission-ai-large-language-models-12-o4-c1', 'solution', 'Every specific causal claim in the model''s explanation is unsupported, its confident tone is not evidence of truth, and Cipher Division must reject the explanation outright -- the Act 23 similarity is still real, but still unexplained.', 25, 2);
